import { collection, getDocs, query, getDoc, doc } from "firebase/firestore";
import { accessories, enrichProductDescription } from "../data/accessories";
import { getModelPreviewUrl } from "../data/modelPreview";
import { db, firebaseEnabled } from "./app";

// Create fallback products from accessories data
const fallbackProducts = accessories.map((accessory) => ({
  id: accessory.id,
  name: accessory.name,
  category: accessory.category,
  price: accessory.price,
  currency: "NPR",
  description: accessory.description,
  previewUrl: accessory.thumbnailUrl,
  modelUrl: accessory.modelUrl,
  thumbnailUrl: accessory.thumbnailUrl,
  tryOnImageUrl: accessory.thumbnailUrl,
  arSupported: accessory.arSupported
}));

const accessoriesById = new Map(accessories.map((accessory) => [accessory.id, accessory]));

function withCatalogDescription(product) {
  const accessory = accessoriesById.get(product.accessoryId ?? product.id);
  if (!accessory) {
    return {
      ...product,
      description: enrichProductDescription(product)
    };
  }

  return {
    ...product,
    description: accessory.description ?? enrichProductDescription(product)
  };
}

function createFallbackProduct(accessory) {
  if (!accessory) {
    return null;
  }

  return {
    id: accessory.id,
    name: accessory.name,
    category: accessory.category,
    price: accessory.price,
    currency: "NPR",
    description: accessory.description,
    previewUrl: accessory.thumbnailUrl,
    modelUrl: accessory.modelUrl,
    thumbnailUrl: accessory.thumbnailUrl,
    tryOnImageUrl: accessory.thumbnailUrl,
    accessoryId: accessory.id,
    arSupported: accessory.arSupported
  };
}

function getFallbackProductById(productId) {
  return createFallbackProduct(accessories.find((accessory) => accessory.id === productId));
}

export async function getProducts() {
  try {
    if (!firebaseEnabled || !db) {
      // Use accessories as fallback
      return fallbackProducts;
    }

    const productsSnapshot = await getDocs(query(collection(db, "products")));
    const products = productsSnapshot.docs.map((productDoc) => ({
      id: productDoc.id,
      ...productDoc.data()
    })).map(withCatalogDescription);

    return products.length > 0 ? products : fallbackProducts;
  } catch {
    return fallbackProducts;
  }
}

export async function getProductById(productId) {
  try {
    if (!firebaseEnabled || !db) {
      return getFallbackProductById(productId);
    }

    const productDoc = await getDoc(doc(db, "products", productId));
    if (productDoc.exists()) {
      return withCatalogDescription({
        id: productDoc.id,
        ...productDoc.data()
      });
    }

    return getFallbackProductById(productId);
  } catch {
    return getFallbackProductById(productId);
  }
}

export async function getProductsByCategory(category) {
  const products = await getProducts();
  return products.filter((p) => p.category === category);
}
